import type { UptimeUwFieldRow } from './types'
/**
 * The ultimate-weapon field map, in its own module.
 *
 * `uptime-core` needs this table and `shared-uptime-inputs` needs
 * `UptimeCoreState`, which made the two import each other. The type edge was
 * erased at build time, so nothing failed -- but a cycle is a cycle to the
 * dependency rules, and it blocked `uptime-core` from leaving `internal/`.
 *
 * The table is data, not logic, so it belongs to neither module. As a leaf both
 * can import, `uptime-core` stops depending on `shared-uptime-inputs` entirely
 * and the cycle is gone rather than merely tolerated.
 */

